import "./App.css";

function App() {
    const [transactions, setTransactions] = useState([]);
    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances />
            <TradeForm />
            <DepositAndWithdrawalForm />
        </div>
    );
}

function Balances() {
    return (
        <div>
            <label>Account Balance</label>
            <input type="text" disabled />
        </div>
    );
}

function TradeForm() {
    return (
        <form className="form">
            <div>
                <label>Stock</label>
                <input type="text" />
            </div>
            <div>
                <label>Shares</label>
                <input type="text" />
            </div>
            <div>
                <label>Price</label>
                <input type="text" />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled />
            </div>
            <button>Buy</button>
            <button>Sell</button>
        </form>
    );
}

function DepositAndWithdrawalForm() {
    return (
        <form className="form">
            <div>
                <label>Amount</label>
                <input type="text" />
            </div>
            <button>Deposit</button>
            <button>Withdraw</button>
        </form>
    );
}

function TransactionTable() {}

function TradesTable() {}

export default App;
